using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class WeatherTool
{
    [McpServerTool, Description("Gets the current weather for a given city.")]
    public static string GetWeather(
        [Description("The city name to get weather for")] string city)
    {
        // Simulated weather data
        var random = new Random(city.GetHashCode());
        var temp = random.Next(-10, 40);
        var conditions = new[] { "Sunny", "Cloudy", "Rainy", "Snowy", "Windy" };
        var condition = conditions[random.Next(conditions.Length)];

        return $"Weather in {city}: {temp}°C, {condition}";
    }
}

using ModelContextProtocol.Server;
using ModelContextProtocol;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigurationResourceProvider
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "MyMcpService",
        ["version"] = "1.0.0",
        ["environment"] = "production",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        Description = "Returns the current application configuration.")]
    public static string GetAppConfiguration()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags",
        Description = "Returns the current feature flag settings.")]
    public static string GetFeatureFlags()
    {
        var features = (Dictionary<string, bool>)AppConfig["features"];
        return JsonSerializer.Serialize(features, new JsonSerializerOptions { WriteIndented = true });
    }
}

