 using ModelContextProtocol.Server;
 using System.ComponentModel;
 using System.Text.Json;

 namespace McpHttpServer;

 [McpServerResourceType]
 public static class ConfigurationResourceProvider
 {
     private static readonly Dictionary<string, object> AppConfig = new()
     {
         ["appName"] = "MyMcpService",
         ["version"] = "1.0.0",
         ["environment"] = "production",
         ["features"] = new Dictionary<string, bool>
         {
             ["darkMode"] = true,
             ["notifications"] = true,
             ["betaFeatures"] = false
         }
     };

     [McpServerResource(UriTemplate = "config://app", Name = "App Configuration")]
     [Description("Returns the current application configuration.")]
     public static string GetAppConfiguration()
     {
         return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
     }

     [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags")]
     [Description("Returns the current feature flag settings.")]
     public static string GetFeatureFlags()
     {
         var features = (Dictionary<string, bool>)AppConfig["features"];
         return JsonSerializer.Serialize(features, new JsonSerializerOptions { WriteIndented = true });
     }
 }

